WIDTH = {"id": 8, "uid": 8, "dept": 16, "amount": 8, "ts": 8, "city": 16, "age": 4}


def Scan(name, cols, rows):
    return {"op": "Scan", "name": name, "cols": list(cols), "rows": rows, "children": []}


def Project(cols, child):
    return {"op": "Project", "cols": list(cols), "children": [child]}


def Join(cond, lkeys, rkeys, left, right):
    return {"op": "Join", "cond": cond, "lkeys": list(lkeys), "rkeys": list(rkeys),
            "children": [left, right]}


def Agg(group, funcs, child):
    return {"op": "Agg", "group": list(group), "funcs": list(funcs), "children": [child]}


def prune(n, need):
    """规则 ColumnPruning：自顶向下把「父节点真正需要的列」推给子节点。"""
    if n["op"] == "Scan":
        keep = [c for c in n["cols"] if c in need]
        m = dict(n)
        m["cols"] = keep
        return m
    if n["op"] == "Project":
        keep = [c for c in n["cols"] if c in need]
        m = dict(n)
        m["cols"] = keep
        m["children"] = [prune(n["children"][0], set(keep))]
        return m
    if n["op"] == "Join":
        m = dict(n)
        m["children"] = [prune(n["children"][0], need | set(n["lkeys"])),
                         prune(n["children"][1], need | set(n["rkeys"]))]
        return m
    if n["op"] == "Agg":
        m = dict(n)
        m["children"] = [prune(n["children"][0], set(n["group"]) | set(n["funcs"]))]
        return m
    m = dict(n)
    m["children"] = [prune(c, need) for c in n["children"]]
    return m


def scans(n, acc=None):
    if acc is None:
        acc = []
    if n["op"] == "Scan":
        acc.append(n)
    for c in n["children"]:
        scans(c, acc)
    return acc


def row_bytes(n):
    return sum(WIDTH[c] for c in n["cols"])


orders = Scan("orders", ["id", "uid", "dept", "amount", "ts"], 1000000)
users = Scan("users", ["uid", "city", "age"], 100000)
plan = Agg(["city"], ["amount"],
           Join("o.uid=u.uid", ["uid"], ["uid"],
                Project(["uid", "dept", "amount"], orders),
                Project(["uid", "city"], users)))

before = scans(plan)
after = scans(prune(plan, {"city", "amount"}))

print("== 裁剪前扫描的列 ==")
tot_b = tot_a = 0
for s in before:
    print("  " + s["name"] + ": " + str(sorted(s["cols"])) + "  列数=" + str(len(s["cols"])) +
          "  每行字节=" + str(row_bytes(s)) + "  总字节=" + str(row_bytes(s) * s["rows"]))
    tot_b += row_bytes(s) * s["rows"]

print("== 裁剪后扫描的列 ==")
for s in after:
    print("  " + s["name"] + ": " + str(sorted(s["cols"])) + "  列数=" + str(len(s["cols"])) +
          "  每行字节=" + str(row_bytes(s)) + "  总字节=" + str(row_bytes(s) * s["rows"]))
    tot_a += row_bytes(s) * s["rows"]

o_before = [s for s in before if s["name"] == "orders"][0]
o_after = [s for s in after if s["name"] == "orders"][0]

print("")
print("orders 扫描列数: " + str(len(o_before["cols"])) + " -> " + str(len(o_after["cols"])))
print("orders 裁剪掉的列: " + str(sorted(set(o_before["cols"]) - set(o_after["cols"]))))
print("总读取字节: " + str(tot_b) + " -> " + str(tot_a))
print("列裁剪生效（列数下降）: " + str(len(o_after["cols"]) < len(o_before["cols"])))
print("未使用的列不再读取: " + str(set(o_after["cols"]) <= set(o_before["cols"])))
print("判据 字节数下降: " + str(tot_a < tot_b) + "   节省倍数 = " + str(round(tot_b / tot_a, 2)))
